import AppKit

/// Polls the general pasteboard (macOS has no change notification) and feeds the store.
@MainActor
final class ClipboardMonitor {
    static let shared = ClipboardMonitor()

    private let pasteboard = NSPasteboard.general
    private var lastChange = NSPasteboard.general.changeCount
    private var timer: Timer?

    /// Password managers and other apps flag secrets with these types; never record them.
    private let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.typeit4me.clipping",
    ]

    private let maxTextLength = 1_000_000
    private let maxImageBytes = 25_000_000

    func start() {
        lastChange = pasteboard.changeCount
        let t = Timer(timeInterval: 0.5, repeats: true) { [weak self] _ in
            Task { @MainActor in self?.poll() }
        }
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    private func poll() {
        guard pasteboard.changeCount != lastChange else { return }
        lastChange = pasteboard.changeCount

        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: ignoredTypes) else { return }

        let source = NSWorkspace.shared.frontmostApplication?.localizedName
        let store = ClipStore.shared

        if let text = pasteboard.string(forType: .string),
           !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            if text.count <= maxTextLength { store.addText(text, source: source) }
            return
        }

        guard UserDefaults.standard.bool(forKey: "captureImages") else { return }
        if let (png, w, h) = pasteboardPNG(), png.count <= maxImageBytes {
            store.addImage(png: png, width: w, height: h, source: source)
        }
    }

    private func pasteboardPNG() -> (Data, Int, Int)? {
        let data = pasteboard.data(forType: .png) ?? pasteboard.data(forType: .tiff)
        guard let data, let rep = NSBitmapImageRep(data: data) else { return nil }
        if pasteboard.data(forType: .png) != nil { return (data, rep.pixelsWide, rep.pixelsHigh) }
        guard let png = rep.representation(using: .png, properties: [:]) else { return nil }
        return (png, rep.pixelsWide, rep.pixelsHigh)
    }

    /// Puts a stored clip back on the clipboard without re-capturing it.
    func copy(_ item: ClipItem) {
        pasteboard.clearContents()
        switch item.kind {
        case .image:
            if let file = item.imageFile,
               let image = NSImage(contentsOf: ClipStore.shared.imagesDirectory.appendingPathComponent(file)) {
                pasteboard.writeObjects([image])
            }
        default:
            pasteboard.setString(item.text ?? "", forType: .string)
        }
        lastChange = pasteboard.changeCount
        ClipStore.shared.markUsed(item.id)
    }
}
